"use strict";(self.webpackChunkreact_ui_animate_docs=self.webpackChunkreact_ui_animate_docs||[]).push([[1836],{4558:e=>{e.exports=JSON.parse('{"pluginId":"default","version":"5.3.2","label":"5.3.2","banner":null,"badge":true,"noIndex":false,"className":"docs-version-5.3.2","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"Getting Started","href":"/docs/getting-started","docId":"getting-started","unlisted":false},{"type":"category","label":"Concept","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"The animate Component","href":"/docs/concept/animate-component","docId":"concept/animate-component","unlisted":false},{"type":"link","label":"useValue","href":"/docs/concept/useValue","docId":"concept/useValue","unlisted":false},{"type":"link","label":"Interpolation","href":"/docs/concept/interpolation","docId":"concept/interpolation","unlisted":false}]},{"type":"category","label":"Animation Modifier","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Animation Modifiers Overview","href":"/docs/animation-modifier/overview","docId":"animation-modifier/overview","unlisted":false},{"type":"link","label":"withSpring","href":"/docs/animation-modifier/withSpring","docId":"animation-modifier/withSpring","unlisted":false},{"type":"link","label":"withTiming","href":"/docs/animation-modifier/withTiming","docId":"animation-modifier/withTiming","unlisted":false},{"type":"link","label":"withDecay","href":"/docs/animation-modifier/withDecay","docId":"animation-modifier/withDecay","unlisted":false},{"type":"link","label":"withSequence","href":"/docs/animation-modifier/withSequence","docId":"animation-modifier/withSequence","unlisted":false},{"type":"link","label":"withDelay","href":"/docs/animation-modifier/withDelay","docId":"animation-modifier/withDelay","unlisted":false},{"type":"link","label":"withLoop","href":"/docs/animation-modifier/withLoop","docId":"animation-modifier/withLoop","unlisted":false}]},{"type":"category","label":"Presence & Exit","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Presence Basics","href":"/docs/presence/presence-basics","docId":"presence/presence-basics","unlisted":false}]},{"type":"category","label":"Interactive Animations","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Hover Animations","href":"/docs/interactive/hover-animations","docId":"interactive/hover-animations","unlisted":false},{"type":"link","label":"Press Animations","href":"/docs/interactive/press-animations","docId":"interactive/press-animations","unlisted":false},{"type":"link","label":"Focus Animations","href":"/docs/interactive/focus-animations","docId":"interactive/focus-animations","unlisted":false},{"type":"link","label":"View Animations","href":"/docs/interactive/view-animations","docId":"interactive/view-animations","unlisted":false}]},{"type":"category","label":"Gesture","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Gestures Overview","href":"/docs/gesture/overview","docId":"gesture/overview","unlisted":false},{"type":"link","label":"useDrag","href":"/docs/gesture/useDrag","docId":"gesture/useDrag","unlisted":false},{"type":"link","label":"useMove","href":"/docs/gesture/useMove","docId":"gesture/useMove","unlisted":false},{"type":"link","label":"useScroll","href":"/docs/gesture/useScroll","docId":"gesture/useScroll","unlisted":false},{"type":"link","label":"useWheel","href":"/docs/gesture/useWheel","docId":"gesture/useWheel","unlisted":false}]},{"type":"category","label":"Hook","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"useOutsideClick","href":"/docs/hooks/useOutsideClick","docId":"hooks/useOutsideClick","unlisted":false},{"type":"link","label":"useScrollProgress","href":"/docs/hooks/useScrollProgress","docId":"hooks/useScrollProgress","unlisted":false},{"type":"link","label":"useInView","href":"/docs/hooks/useInView","docId":"hooks/useInView","unlisted":false}]}]},"docs":{"animation-modifier/overview":{"id":"animation-modifier/overview","title":"Animation Modifiers Overview","description":"Animation modifiers are functions that tell useValue how to animate. Without a modifier, values change instantly. With modifiers, you get smooth, controlled transitions.","sidebar":"tutorialSidebar"},"animation-modifier/withDecay":{"id":"animation-modifier/withDecay","title":"withDecay","description":"The withDecay modifier simulates natural momentum with friction. It\'s perfect for scenarios where you want values to gradually slow down, like a thrown ball losing speed or a scroll that decelerates naturally.","sidebar":"tutorialSidebar"},"animation-modifier/withDelay":{"id":"animation-modifier/withDelay","title":"withDelay","description":"The withDelay modifier adds a pause before an animation starts. Perfect for creating staggered animations, sequential reveals, and timed sequences where you need precise control over when animations begin.","sidebar":"tutorialSidebar"},"animation-modifier/withLoop":{"id":"animation-modifier/withLoop","title":"withLoop","description":"The withLoop modifier repeats an animation a specified number of times or infinitely. Perfect for loading indicators, pulsing effects, continuous animations, and any animation that needs to repeat.","sidebar":"tutorialSidebar"},"animation-modifier/withSequence":{"id":"animation-modifier/withSequence","title":"withSequence","description":"The withSequence modifier chains multiple animations together, executing them one after another in order. Perfect for creating complex, multi-step animations where each step must complete before the next begins.","sidebar":"tutorialSidebar"},"animation-modifier/withSpring":{"id":"animation-modifier/withSpring","title":"withSpring","description":"The withSpring modifier creates natural, physics-based animations using spring physics. It\'s perfect for UI elements that should feel alive and responsive, like buttons, cards, modals, and interactive components.","sidebar":"tutorialSidebar"},"animation-modifier/withTiming":{"id":"animation-modifier/withTiming","title":"withTiming","description":"The withTiming modifier creates precise, time-based animations with exact durations. Unlike withSpring which uses physics, withTiming gives you complete control over how long an animation takes and how it accelerates/decelerates.","sidebar":"tutorialSidebar"},"concept/animate-component":{"id":"concept/animate-component","title":"The animate Component","description":"The ` component is the foundation of React UI Animate. It works exactly like regular HTML elements (div, span, button`, etc.) but understands animated values and provides powerful declarative animation props.","sidebar":"tutorialSidebar"},"concept/interpolation":{"id":"concept/interpolation","title":"Interpolation","description":"Interpolation is the process of mapping one range of values to another.\\\\","sidebar":"tutorialSidebar"},"concept/useValue":{"id":"concept/useValue","title":"useValue","description":"The useValue hook is the core of React UI Animate. It creates animated values that update smoothly without causing React re-renders, making your animations performant and your code simple.","sidebar":"tutorialSidebar"},"gesture/overview":{"id":"gesture/overview","title":"Gestures Overview","description":"Gesture hooks in React UI Animate provide a powerful, declarative way to handle user interactions. Whether you\'re building draggable cards, scroll-based animations, or custom cursor effects, these hooks simplify complex gesture handling.","sidebar":"tutorialSidebar"},"gesture/useDrag":{"id":"gesture/useDrag","title":"useDrag","description":"The useDrag hook enables drag gesture recognition on any DOM element. It handles pointer events, calculates movement, offset, and velocity, providing a clean callback-based API for building draggable interfaces.","sidebar":"tutorialSidebar"},"gesture/useMove":{"id":"gesture/useMove","title":"useMove","description":"The useMove hook tracks pointer movement without requiring a press or drag. It provides real-time feedback about cursor position, movement, and velocity - perfect for hover effects, custom cursors, and interactive elements that respond to mouse position.","sidebar":"tutorialSidebar"},"gesture/useScroll":{"id":"gesture/useScroll","title":"useScroll","description":"The useScroll hook captures scroll activity on any DOM element or the window. It provides detailed scroll information including position, velocity, and movement deltas - perfect for scroll-triggered animations, parallax effects, and progress indicators.","sidebar":"tutorialSidebar"},"gesture/useWheel":{"id":"gesture/useWheel","title":"useWheel","description":"The useWheel hook listens to wheel/touchpad gestures and provides detailed information about wheel movement, velocity, and accumulated offset. Perfect for zoom interactions, custom scroll behavior, and gesture-driven UIs.","sidebar":"tutorialSidebar"},"getting-started":{"id":"getting-started","title":"Getting Started","description":"Welcome to React UI Animate! This library makes it incredibly simple to create smooth, performant animations and interactive gestures in your React applications. Whether you\'re building a simple fade-in effect or complex gesture-based interactions, React UI Animate provides the tools you need.","sidebar":"tutorialSidebar"},"hooks/useInView":{"id":"hooks/useInView","title":"useInView","description":"The useInView hook detects when an element enters or leaves the viewport using the Intersection Observer API. It\'s perfect for scroll-triggered animations, lazy loading, analytics tracking, and performance optimizations.","sidebar":"tutorialSidebar"},"hooks/useOutsideClick":{"id":"hooks/useOutsideClick","title":"useOutsideClick","description":"The useOutsideClick hook allows you to detect clicks that occur outside a specific DOM element, triggering a callback function when this happens.\\\\","sidebar":"tutorialSidebar"},"hooks/useScrollProgress":{"id":"hooks/useScrollProgress","title":"useScrollProgress","description":"The useScrollProgress hook provides an animated value that tracks scroll progress (0 to 1) for any scrollable element or the window. It\'s perfect for creating scroll-based animations, progress indicators, and scroll-triggered effects.","sidebar":"tutorialSidebar"},"interactive/focus-animations":{"id":"interactive/focus-animations","title":"Focus Animations","description":"Focus animations provide visual feedback when users navigate with keyboards or assistive technologies. The focus prop triggers animations when elements receive focus, improving accessibility and user experience.","sidebar":"tutorialSidebar"},"interactive/hover-animations":{"id":"interactive/hover-animations","title":"Hover Animations","description":"Hover animations are one of the most common interactions in web applications. React UI Animate makes it easy to create smooth, responsive hover effects using the hover prop.","sidebar":"tutorialSidebar"},"interactive/press-animations":{"id":"interactive/press-animations","title":"Press Animations","description":"Press animations provide immediate visual feedback when users interact with elements. The press prop triggers animations on mousedown/touchstart, making your UI feel responsive and interactive.","sidebar":"tutorialSidebar"},"interactive/view-animations":{"id":"interactive/view-animations","title":"View Animations","description":"View animations automatically trigger when elements enter the viewport. The view prop uses Intersection Observer to detect when elements become visible, perfect for scroll-triggered reveals and progressive disclosure.","sidebar":"tutorialSidebar"},"presence/presence-basics":{"id":"presence/presence-basics","title":"Presence Basics","description":"The Presence component enables smooth exit animations when components leave the DOM. Unlike conditional rendering which removes elements instantly, Presence allows you to animate components out before they\'re removed.","sidebar":"tutorialSidebar"}}}')}}]);